<?php
/**
 * Disposable real-core PDF preview and wp_unique_filename regression fixtures.
 * Never run against a real site. Companion metadata is synthetic; PDF metadata
 * and filenames are generated by WordPress 7.1.3 itself.
 */
if (getenv('ESP_ALLOW_DISPOSABLE_DB') !== '1' || !getenv('ESP_WP_ROOT')) {
    exit(1);
}
define('WP_INSTALLING', true);
require rtrim(getenv('ESP_WP_ROOT'), '/') . '/wp-load.php';
wp_installing(false);
if (strpos(DB_NAME, 'esp_') !== 0) {
    exit(1);
}
require_once ABSPATH . 'wp-admin/includes/image.php';
require_once ABSPATH . 'wp-admin/includes/file.php';
$uploads = wp_upload_dir();
$root = $uploads['basedir'];
$marker_for_jpeg = static function ($jpeg, $marker) {
    if (substr($jpeg, 0, 2) !== "\xFF\xD8") {
        throw new RuntimeException('Expected JPEG source');
    }
    return substr($jpeg, 0, 2) . "\xFF\xFE" .
        pack('n', strlen($marker) + 2) . $marker . substr($jpeg, 2);
};
$protect_attachment = static function ($id) use ($wpdb) {
    if (is_wp_error($id) || !$id) {
        throw new RuntimeException('Cannot insert protected fixture attachment');
    }
    if (!$wpdb->insert($wpdb->postmeta, [
        'post_id' => $id,
        'meta_key' => '_esp_media_protected_path_id',
        'meta_value' => 'path_http',
    ])) {
        throw new RuntimeException('Cannot mark fixture attachment protected');
    }
};
// Generate a real PDF document without shipping a third-party PDF fixture.
$ps = $root . '/esp42-report.ps';
$pdf = $root . '/esp42-report.pdf';
file_put_contents($ps, "%!PS-Adobe-3.0\n<< /PageSize [420 360] >> setpagedevice\n" .
    "/Helvetica findfont 30 scalefont setfont\n70 220 moveto (ESP42 protected PDF) show\nshowpage\n");
$output = [];
$exit_code = 0;
exec('gs -q -dSAFER -dBATCH -dNOPAUSE -sDEVICE=pdfwrite -sOutputFile=' .
    escapeshellarg($pdf) . ' ' . escapeshellarg($ps) . ' 2>&1', $output, $exit_code);
unlink($ps);
if ($exit_code !== 0 || !is_file($pdf)) {
    throw new RuntimeException('Cannot generate disposable PDF: ' . implode(' ', $output));
}
// Force core wp_unique_filename() to choose "-1" for the PDF preview.
file_put_contents($root . '/esp42-report-pdf.jpg',
    file_get_contents($root . '/esp31-protected.jpg'));
$pdf_id = wp_insert_attachment([
    'post_title' => 'ESP42 protected PDF',
    'post_mime_type' => 'application/pdf',
    'post_status' => 'inherit',
], $pdf);
$protect_attachment($pdf_id);
update_attached_file($pdf_id, $pdf);
$pdf_meta = wp_generate_attachment_metadata($pdf_id, $pdf);
if (!is_array($pdf_meta) || isset($pdf_meta['file']) ||
    !isset($pdf_meta['sizes']['full']['file'], $pdf_meta['sizes']['thumbnail']['file'])) {
    throw new RuntimeException('WordPress did not generate PDF metadata with no file key');
}
wp_update_attachment_metadata($pdf_id, $pdf_meta);
$full = $pdf_meta['sizes']['full']['file'];
$thumb = $pdf_meta['sizes']['thumbnail']['file'];
if (!preg_match('/^esp42-report-pdf-[1-9][0-9]*\.jpg$/', $full) ||
    !is_file($root . '/' . $full) || !is_file($root . '/' . $thumb)) {
    throw new RuntimeException('WordPress did not use unique PDF preview names');
}

// Use WordPress' real collision naming for a second protected JPEG derivative.
$jpeg_id = (int) $wpdb->get_var("SELECT ID FROM {$wpdb->posts}
    WHERE post_type = 'attachment' AND post_title = 'ESP31 protected JPEG' LIMIT 1");
$jpeg_meta = wp_get_attachment_metadata($jpeg_id, true);
if ($jpeg_id <= 0 || !is_array($jpeg_meta)) {
    throw new RuntimeException('Missing protected JPEG parent attachment');
}
$numbered_jpeg = wp_unique_filename($root, 'esp31-protected-150x150.jpg');
if (!preg_match('/^esp31-protected-150x150-[1-9][0-9]*\.jpg$/', $numbered_jpeg)) {
    throw new RuntimeException('WordPress did not number the duplicate JPEG thumbnail');
}
file_put_contents($root . '/' . $numbered_jpeg,
    $marker_for_jpeg(file_get_contents($root . '/esp31-protected.jpg'),
        'ESP42_NUMBERED_IMAGE'));
$jpeg_meta['sizes']['duplicate'] = [
    'file' => $numbered_jpeg, 'width' => 150, 'height' => 150, 'mime-type' => 'image/jpeg',
];
wp_update_attachment_metadata($jpeg_id, $jpeg_meta);

// WordPress 7.1 companions can retain the source extension in their name.
$gif = $root . '/esp42-clip.gif';
file_put_contents($gif, base64_decode('R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=', true));
$gif_id = wp_insert_attachment([
    'post_title' => 'ESP42 protected GIF',
    'post_mime_type' => 'image/gif',
    'post_status' => 'inherit',
], $gif);
$protect_attachment($gif_id);
update_attached_file($gif_id, $gif);
file_put_contents($root . '/esp42-clip.gif-poster.jpg',
    file_get_contents($root . '/esp31-protected.jpg'));
$gif_poster = wp_unique_filename($root, 'esp42-clip.gif-poster.jpg');
if (!preg_match('/^esp42-clip\.gif-poster-[1-9][0-9]*\.jpg$/', $gif_poster)) {
    throw new RuntimeException('WordPress did not number the companion collision');
}
file_put_contents($root . '/' . $gif_poster,
    $marker_for_jpeg(file_get_contents($root . '/esp31-protected.jpg'),
        'ESP42_NUMBERED_GIF_POSTER'));
wp_update_attachment_metadata($gif_id, [
    'file' => 'esp42-clip.gif', 'animated_video_poster' => $gif_poster,
]);
$manifest = [
    'pdf_original' => 'esp42-report.pdf',
    'pdf_full' => $full,
    'pdf_thumb' => $thumb,
    // Python fixture guard expects every entry to start esp42-. The real
    // numbered JPEG is an esp31 name, so give it its own guarded exception.
    'image_unique' => $numbered_jpeg,
    'gif_poster_unique' => $gif_poster,
];
if (file_put_contents($root . '/.esp42-pdf-fixture.json',
    json_encode($manifest, JSON_UNESCAPED_SLASHES)) === false) {
    throw new RuntimeException('Cannot write disposable fixture manifest');
}
echo 'PASS: real WordPress PDF metadata and numbered filenames: ' .
    json_encode($manifest, JSON_UNESCAPED_SLASHES) . "\n";
